53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	
57	const BASE_PREMIUMS: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
67	const COMPONENT_BLOCK_SIZE = 3;
68	const COMPONENT_BLOCK_PREMIUM = 60;
69	
70	const roundUpInMHPCOsFavor = Math.ceil;
71	
72	const basePremiumFor = (type: string, count: number): number => {
73	  const isComponentBlock =
74	    COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
75	  return isComponentBlock
76	    ? COMPONENT_BLOCK_PREMIUM
77	    : count * BASE_PREMIUMS[type];
78	};
79	
80	const countItemsByType = (items: QuoteItem[]): Map<string, number> => {
81	  const countsByType = new Map<string, number>();
82	  for (const item of items) {
83	    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
84	  }
85	  return countsByType;
86	};
87	
88	const quotePremium = (items: QuoteItem[], customer: Customer): number => {
89	  const basePremium = [...countItemsByType(items)].reduce(
90	    (total, [type, count]) => total + basePremiumFor(type, count),
91	    0,
92	  );
93	  const curseSurcharge = items.reduce(
94	    (total, item) =>
95	      total + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0),
96	    0,
97	  );
98	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_RATE;
99	  const loyaltyDiscount =
100	    customer.yearsWithMHPCO >= 2 ? basePremium * 0.2 : 0;
101	  return roundUpInMHPCOsFavor(
102	    basePremium +
103	      curseSurcharge +
104	      firstInsuranceSurcharge -
105	      loyaltyDiscount +
106	      PROCESSING_FEE,
107	  );
108	};
109	
110	export const runScenario = (scenario: Scenario): ScenarioOutput => {
111	  const quoteStep = scenario.steps[0] as QuoteStep;
112	  return {
113	    results: [{ premium: quotePremium(quoteStep.items, scenario.customer) }],
114	  };
115	};
